def findWordsInGrid(board: list[list[str]], words: list[str]) -> list[str]:
    trie = {}
    for w in words:
        node = trie
        for ch in w:
            node = node.setdefault(ch, {})
        node['#'] = w
    m, n = len(board), len(board[0])
    found = set()
    def dfs(r, c, node):
        ch = board[r][c]
        if ch not in node: return
        curr = node[ch]
        if '#' in curr:
            found.add(curr['#'])
        board[r][c] = '*'
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and board[nr][nc] != '*':
                dfs(nr, nc, curr)
        board[r][c] = ch
    for i in range(m):
        for j in range(n):
            dfs(i, j, trie)
    return sorted(list(found))

